// بناء اللوحة: 6 فئات × 5 قيم = 30 سؤال
function buildBoard(cats, pickQ) {
  return cats.map((cat) => ({
    cat,
    tiles: BOARD_VALUES.map((pts) => {
      const q = pickQ(cat, pts);
      return { pts, state: q ? "available" : "locked", q };
    }),
  }));
}
