const INVENTIVE = ["المغالطات المنطقية", "طب وصحة", "اقتصاد وأعمال", "موسيقى", "عمارة ومعالم", "لغات وشعوب", "مقولات", "مين الشخصية؟", "خمّن البوس", "خمّن اللعبة", "بوسات إلدن رينق", "لعبة الحروف", "منطق وألغاز", "أمثال ومصطلحات", "طعام ومطبخ", "حيوانات", "فضاء", "جسم الإنسان", "السعودية", "سيارات", "اختراعات", "أعلام", "شكل ورسم", "وين المكان؟", "وش الغرض؟",
  "الرابط المشترك", "قبل ولا بعد؟", "إيموجي", "دليلين", "الأغرب", "لو كنت مكانك"];
const CLASSIC = CATS.filter((c) => !INVENTIVE.includes(c));
// نضمن 6 فئات مبتكرة + 3 كلاسيكية كل جولة (9 خيارات)
